6	
7	const dataHora = (iso) => iso ? new Date(iso).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) : '—';
8	const agora = () => new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
9	
10	const TIPO_LABEL = { fixo: 'Fixo', percentual: '% do frete', km: 'R$/km', km_fallback: 'Km (padrão)' };
11	const traduzTipo = (t) => TIPO_LABEL[t] ?? t ?? '—';
12	
13	const buildPrintHtml = (motoboys, entregas, restauranteNome, label, motoboyNome) => {
14	  const rows = motoboys.map((m) => `<tr>
15	    <td>${m.nome}</td>
16	    <td class="right">${m.entregas}</td>
17	    <td class="right">${fmt(m.total_frete_repassado)}</td>
18	    <td class="right">${fmt(m.total_adicional)}</td>
19	    <td class="right bold green">${fmt(m.total_comissao)}</td>
20	  </tr>`).join('');
21	
22	  const entregaRows = (entregas ?? []).map((e) => `<tr>
23	    <td>${dataHora(e.data)}</td>
24	    <td>${e.motoboy_nome}</td>
25	    <td>#${e.pedido_id}</td>
26	    <td>${traduzTipo(e.tipo)}</td>
27	    <td class="right">${e.distancia_km != null ? `${e.distancia_km} km` : '—'}</td>
28	    <td class="right">${fmt(e.frete_repassado)}</td>
29	    <td class="right">${fmt(e.adicional)}</td>
30	    <td class="right bold">${fmt(e.comissao_valor)}</td>
31	  </tr>`).join('');
32	
33	  const eFrete = (entregas ?? []).reduce((s, e) => s + e.frete_repassado, 0);
34	  const eAdicional = (entregas ?? []).reduce((s, e) => s + e.adicional, 0);
35	  const eComissao = (entregas ?? []).reduce((s, e) => s + e.comissao_valor, 0);
36	  const entregaTotalRow = (entregas ?? []).length ? `<tr>
