1	import { Injectable, Logger } from '@nestjs/common';
2	import * as crypto from 'crypto';
3	import { SupabaseService } from '../supabase/supabase.service';
4	import { GeocodingService } from './geocoding.service';
5	import { Coordenadas, haversineKm } from '../common/geo.util';
6	
7	interface PedidoParaComissao {
8	  id: number;
9	  restaurant_id: number;
10	  total: number;
11	  frete_cobrado: number;
12	  customer_id: number | null;
13	}
14	
15	@Injectable()
16	export class ComissaoService {
17	  private readonly logger = new Logger(ComissaoService.name);
18	
19	  constructor(
20	    private supabase: SupabaseService,
21	    private geocoding: GeocodingService,
22	  ) {}
23	
24	  // Idempotente via UNIQUE(pedido_id) — chamado sempre que um pedido é marcado como entregue.
25	  async registrarComissaoEntrega(pedido: PedidoParaComissao, motoboyId: number) {
26	    const { data: existente } = await this.supabase.client
27	      .from('motoboy_comissoes')
28	      .select('id')
29	      .eq('pedido_id', pedido.id)
30	      .maybeSingle();
31	    if (existente) return existente;
32	
33	    const { data: restaurant } = await this.supabase.client
34	      .from('restaurants')
35	      .select(
36	        'motoboy_comissao_tipo, motoboy_comissao_valor_fixo, motoboy_comissao_percentual, motoboy_comissao_valor_km, motoboy_comissao_km_fallback, lat, lng',
37	      )
38	      .eq('id', pedido.restaurant_id)
39	      .maybeSingle();
40	    if (!restaurant) return null;
41	
42	    // O motoboy sempre recebe o frete cobrado do cliente — o tipo configurado
43	    // (fixo/percentual/km) é um ADICIONAL somado em cima disso, não substituto.
44	    const freteRepassado = Number(pedido.frete_cobrado ?? 0);
45	    let tipo = restaurant.motoboy_comissao_tipo as string;
46	    let adicional = 0;
47	    let distanciaKm: number | null = null;
48	    let valorPorKm: number | null = null;
49	    let percentual: number | null = null;
50	    let valorBase = 0;
51	
52	    if (tipo === 'fixo') {
53	      valorBase = Number(restaurant.motoboy_comissao_valor_fixo);
54	      adicional = valorBase;
55	    } else if (tipo === 'percentual') {
56	      percentual = Number(restaurant.motoboy_comissao_percentual);
57	      valorBase = freteRepassado;
58	      adicional = freteRepassado * (percentual / 100);
59	    } else if (tipo === 'km') {
60	      const distancia = await this.calcularDistanciaPedido(pedido.customer_id, restaurant.lat, restaurant.lng);
61	      if (distancia !== null) {
62	        distanciaKm = parseFloat(distancia.toFixed(2));
63	        valorPorKm = Number(restaurant.motoboy_comissao_valor_km);
64	        adicional = distancia * valorPorKm;
65	      } else {
66	        tipo = 'km_fallback';
67	        valorBase = Number(restaurant.motoboy_comissao_km_fallback);
68	        adicional = valorBase;
69	      }
70	    }
71	
72	    const comissaoValor = freteRepassado + adicional;
73	
74	    const { data, error } = await this.supabase.client
75	      .from('motoboy_comissoes')
76	      .insert({
77	        motoboy_id: motoboyId,
78	        restaurant_id: pedido.restaurant_id,
79	        pedido_id: pedido.id,
80	        tipo,
81	        valor_base: valorBase,
82	        frete_repassado: parseFloat(freteRepassado.toFixed(2)),
83	        percentual,
84	        distancia_km: distanciaKm,
85	        valor_por_km: valorPorKm,
86	        comissao_valor: parseFloat(comissaoValor.toFixed(2)),
87	      })
88	      .select()
89	      .single();
90	
91	    if (error) {
92	      // Corrida (dupla chamada) esbarra no UNIQUE(pedido_id) — não é um erro fatal aqui.
93	      this.logger.warn(`Falha ao registrar comissão do pedido ${pedido.id}: ${error.message}`);
94	      return null;
95	    }
96	    return data;
97	  }
98	
99	  private async calcularDistanciaPedido(
100	    customerId: number | null,
101	    restLat: number | null,
102	    restLng: number | null,
103	  ): Promise<number | null> {
104	    if (!customerId || restLat == null || restLng == null) return null;
105	
106	    const { data: customer } = await this.supabase.client
107	      .from('customers')
108	      .select('lat, lng, address_json')
109	      .eq('id', customerId)
110	      .maybeSingle();
111	    if (!customer) return null;
112	
113	    let { lat, lng } = customer;
114	    if (lat == null || lng == null) {
115	      // Best-effort: geocodifica agora caso não tenha sido feito no checkout.
116	      const enderecoTexto = this.formatarEndereco(customer.address_json);
117	      const coords = await this.geocoding.geocodeEndereco(enderecoTexto);
118	      if (!coords) return null;
119	
120	      lat = coords.lat;
121	      lng = coords.lng;
122	      const hash = crypto.createHash('md5').update(JSON.stringify(customer.address_json ?? {})).digest('hex');
123	      await this.supabase.client
124	        .from('customers')
125	        .update({ lat, lng, address_geocode_hash: hash, address_geocoded_at: new Date().toISOString() })
126	        .eq('id', customerId);
127	    }
128	
129	    return haversineKm({ lat: restLat, lng: restLng }, { lat, lng });
130	  }
131	
132	  private formatarEndereco(addressJson: any): string {
133	    if (!addressJson) return '';
134	    const { logradouro, numero, bairro, cidade, estado, cep } = addressJson;
135	    return [logradouro, numero, bairro, cidade, estado, cep].filter(Boolean).join(', ');
136	  }
137	}
